package com.nbi.etag.model;

import java.math.BigDecimal;

public class Account {
    private String id;
    private String holderName;
    private String phone;
    private BigDecimal balance;
    private long version; // drives the ETag; bumped on every change

    public Account(String id, String holderName, String phone, BigDecimal balance) {
            this.id = id;
            this.holderName = holderName
            this.phone = phone;
        this.balance = balance; this.version = 1;
    }
    public String getId() { return id; }
    public String getHolderName() { return holderName; }
    public String getPhone() { return phone; }
    public void setPhone(String p) { this.phone = p; }
    public BigDecimal getBalance() { return balance; }
    public long getVersion() { return version; }
    public void bumpVersion() { this.version++; }
}
```

