package com.nbi.etag.service;

import com.nbi.etag.dto.AccountUpdate;
import com.nbi.etag.model.Account;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class AccountService {
    private final Map<String, Account> store = new HashMap<>();

    public AccountService() {
        store.put("CUR3001", new Account("CUR3001", "Priya & Rajesh (joint)",
                "9990001111", new BigDecimal("250000.00")));
    }

    public Account find(String id) { return store.get(id); }

    public Account update(String id, AccountUpdate u) {
        Account a = store.get(id);
        a.setPhone(u.phone());
        a.bumpVersion(); // version changes → ETag changes
        return a;
    }
}
