// ─── File: src/main/java/com/nbi/etag/controller/AccountController.java ───
package com.nbi.etag.controller;

import com.nbi.etag.dto.AccountUpdate;
import com.nbi.etag.model.Account;
import com.nbi.etag.service.AccountService;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountService service;
    public AccountController(AccountService service) { this.service = service; }

    private String etagOf(Account a) { return "\"" + a.getVersion() + "\""; }

    // Conditional GET: 304 when the client's ETag still matches → saves bandwidth.
    @GetMapping("/{id}")
    public ResponseEntity<Account> get(@PathVariable String id,
            @RequestHeader(value = "If-None-Match", required = false) String ifNoneMatch) {
        Account a = service.find(id);
        if (a == null) return ResponseEntity.notFound().build();
        String etag = etagOf(a);
        if (etag.equals(ifNoneMatch)) {
            return ResponseEntity.status(HttpStatus.NOT_MODIFIED).eTag(etag).build(); // 304
        }
        return ResponseEntity.ok().eTag(etag).body(a); // 200 + ETag + body
    }

    // Conditional update: 412 when the resource changed underneath → optimistic concurrency.
    @PutMapping("/{id}")
    public ResponseEntity<Account> update(@PathVariable String id,
            @RequestHeader("If-Match") String ifMatch, @RequestBody AccountUpdate body) {
        Account a = service.find(id);
        if (a == null) return ResponseEntity.notFound().build();
        if (!etagOf(a).equals(ifMatch)) {
            return ResponseEntity.status(HttpStatus.PRECONDITION_FAILED).build(); // 412
        }
        Account updated = service.update(id, body);
        return ResponseEntity.ok().eTag(etagOf(updated)).body(updated);
    }
}
```
